  { "cgn", "n", L4, "Advanced", "Change the current or next search match. Use dot to change another match.", "* then cgnnewName<Esc>; . repeats; n skips a match.", help = "gn", rel = { "gn", "*", "." } },
  { "gn", "n,x,o", L4, "Advanced", "Select the current or next search match. Operators can use it too.", "/foo<CR> then dgn or cgn.", help = "gn", rel = { "cgn" } },
