  { "@:", "n", L4, "Advanced", "Repeat the last Ex command (a command entered after a colon).", "@:; then @@ repeats it again.", help = "@:", rel = { "." } },
  { "&", "n", L4, "Advanced", "Repeat the last substitution on this line without its flags.", "&; g& repeats across the file using the previous flags.", help = "&", rel = { ":s" } },
  { "c_<C-r><C-w>", "c", L4, "Command-line", "In Command-line Mode, insert the word under the cursor.", ":%s/<C-r><C-w>/newName/g", help = "c_CTRL-R_CTRL-W", rel = { "i_<C-r>" } },
  { "q:", "n", L4, "Command-line", "Open command history for editing with Vim keys; Enter runs a command.", "q: for commands; q/ for search history.", help = "q:", rel = { "<leader>:" } },
  { "<leader>:", "n", L4, "Command-line", "Open command history in a picker.", "<leader>:", src = "plugin", rel = { "q:" } },
