  { ":read", "c", L4, "Advanced", "Read a file or command output into the buffer.", ":r !date; :r !go env GOPATH", help = ":read", rel = { "!" } },
  { "<C-a>", "n,x", L4, "Advanced", "Increase a number. In Visual Mode, g Ctrl-a creates an increasing sequence.", "5<C-a>; select lines of numbers, then g<C-a>.", help = "CTRL-A", rel = { "<C-x>" } },
